export type Transaction = {
  contractAddress?: string | null;
  /** #49: human-readable failure explanation */
  failureReason?: string | null;
  /** Fee charged, in stroops */
  feeCharged?: string | null;
  /** CAP-0077: transaction touches a consensus-frozen ledger key */
  freezeViolation?: boolean;
  /** Decoded function arguments (key/value map) */
  functionArgs?: Record<string, unknown> | null;
  functionName?: string | null;
  hash?: string;
  /** Plain-English summary, e.g. "Address X swapped 100 USDC → 98.7 XLM" */
  humanReadable?: string | null;
  ledgerCloseTime?: string;
  ledgerSequence?: number;
  /** #48: CPU, memory, and ledger footprint metrics */
  sorobanResources?: Record<string, unknown> | null;
  sourceAccount?: string;
  /** success | failed */
  status?: string;
};

export type TrustPath = {
  chainIds?: Array<string>;
  distance?: number;
  from?: string;
  path?: Array<string> | null;
  to?: string;
};

export type VerifiedIdentityLink = {
  address?: string;
  canonicalAddress?: string;
  chainId?: string;
  messageHash?: string;
  verified?: boolean;
};

export type VestingSchedule = {
  /** Decimal serialised as a string */
  amountPerPeriod?: string | null;
  beneficiary?: string;
  /** Decimal serialised as a string */
  cliffAmount?: string | null;
  cliffDate?: string | null;
  contractAddress?: string;
  detectedAt?: string;
  endDate?: string;
  id?: string;
  /** Decimal serialised as a string */
  nextUnlockAmount?: string | null;
  nextUnlockDate?: string | null;
  periodSeconds?: number | null;
  periodsTotal?: number | null;
  sourceTx?: string | null;
  startDate?: string;
  /** e.g. active | completed | cancelled */
  status?: string;
  tokenAddress?: string;
  tokenSymbol?: string | null;
  /** Decimal serialised as a string (raw base units) */
  totalAmount?: string;
  /** Decimal serialised as a string */
  totalClaimed?: string;
  /** Decimal serialised as a string */
  totalUnlocked?: string;
  /** e.g. linear | cliff | stepped */
  vestingType?: string;
};

export type VulnerabilitySource = {
  active?: boolean;
  createdAt?: string;
  feedUrl?: string | null;
  id?: string;
  lastFetchAt?: string | null;
  /** Unique source identifier, e.g. NVD_CVE, GHSA, COMMUNITY */
  name?: string;
  /** Feed type: cve | ghsa | manual | onchain */
  sourceType?: string;
  updatedAt?: string;
};

export type WebhookSubscription = {
  active?: boolean;
  contractAddress?: string | null;
  createdAt?: string;
  eventType?: string | null;
  id?: string;
  topicSymbol?: string | null;
  url?: string;
};

export type ZodFlattenedError = {
  error?: {
    fieldErrors?: Record<string, Array<string>>;
    formErrors?: Array<string>;
  };
};

export type ZodValidationError = {
  /** Zod validation issues from the failed parse */
  error?: Array<{
    code?: string;
    expected?: string;
    message?: string;
    path?: Array<string>;
    received?: string;
  }>;
};
